#!/usr/bin/env python3
"""What an options backtest gets wrong when it marks positions to intrinsic value.

An equity backtest ends a position when you sell it. An options position can end
in five different ways, and four of them are decided by someone else:

    you close it          you control this
    it expires worthless  you control nothing, but the outcome is clean
    it expires ITM        the OCC exercises it for you, by exception
    it is assigned early  the SHORT side finds out after the fact
    the underlying pins   you do not know your Monday exposure until Saturday

A backtest that computes `max(S - K, 0)` at expiry and stops has modelled the
second and third cases and silently assumed the other three never happen. This
script prices what that assumption costs.

Run:  python option_lifecycle.py

QuantLib is optional. Without it the binomial tree here supplies the American
values, and where QuantLib IS importable every number is checked against it.
"""
from __future__ import annotations

import numpy as np

# --------------------------------------------------------------------------
# A CRR binomial tree, so this file does not need QuantLib to make its point.
# --------------------------------------------------------------------------


def crr(S: float, K: float, r: float, q: float, sigma: float, T: float,
        steps: int = 800, call: bool = True, american: bool = True) -> float:
    dt = T / steps
    u = np.exp(sigma * np.sqrt(dt))
    d = 1.0 / u
    p = (np.exp((r - q) * dt) - d) / (u - d)
    disc = np.exp(-r * dt)

    j = np.arange(steps + 1)
    ST = S * u ** (steps - j) * d ** j
    v = np.maximum(ST - K, 0.0) if call else np.maximum(K - ST, 0.0)

    for i in range(steps - 1, -1, -1):
        v = disc * (p * v[:-1] + (1.0 - p) * v[1:])
        if american:
            Si = S * u ** (i - np.arange(i + 1)) * d ** np.arange(i + 1)
            ex = np.maximum(Si - K, 0.0) if call else np.maximum(K - Si, 0.0)
            v = np.maximum(v, ex)
    return float(v[0])


# --------------------------------------------------------------------------
# 1. Early exercise is not a rounding error on a dividend payer
# --------------------------------------------------------------------------


def early_exercise_premium(S=100.0, K=90.0, r=0.05, sigma=0.20, T=30 / 365):
    rows = []
    for q in (0.00, 0.02, 0.05, 0.10, 0.20):
        eur = crr(S, K, r, q, sigma, T, american=False)
        ame = crr(S, K, r, q, sigma, T, american=True)
        rows.append((q, eur, ame, ame - eur, S - K))
    return rows


# --------------------------------------------------------------------------
# 2. Pin risk: at expiry, near the strike, your Monday exposure is a coin flip
# --------------------------------------------------------------------------


def pin_exposure(K=100.0, contracts=10, multiplier=100, band=0.05):
    """A short call pinned at the strike. Assignment is the counterparty's choice."""
    out = []
    for S in (K - band, K - 0.01, K, K + 0.01, K + band):
        itm = S > K
        # The OCC exercises by exception at $0.01 in the money, but the holder
        # may always submit contrary instructions, and a short may be assigned
        # on any ITM contract regardless of how far.
        auto = "auto-exercised" if S - K >= 0.01 else "expires"
        shares = -contracts * multiplier if itm else 0
        out.append((S, S - K, auto, shares, abs(shares) * S))
    return out


# --------------------------------------------------------------------------
# 3. What the two accounting methods produce on one short-call position
# --------------------------------------------------------------------------


def covered_call_pnl(S0=100.0, K=105.0, premium=2.50, contracts=10, multiplier=100,
                     dividend=1.20, S_exdiv=112.0, S_expiry=110.0):
    """A covered call through an ex-dividend date, priced two ways.

    naive   : hold to expiry, settle at intrinsic, collect the dividend
    correct : the short call is assigned the day before ex-dividend because its
              remaining time value is below the dividend, so the shares are
              called away and the dividend is NOT received
    """
    n = contracts * multiplier
    prem = premium * n

    naive_stock = (S_expiry - S0) * n
    naive_div = dividend * n
    naive_call = -max(S_expiry - K, 0.0) * n
    naive = naive_stock + naive_div + naive_call + prem

    # assigned at the ex-dividend date: stock sold at K, no dividend
    corr_stock = (K - S0) * n
    corr_div = 0.0
    corr_call = 0.0                      # extinguished by assignment
    correct = corr_stock + corr_div + corr_call + prem

    return {
        "naive_total": naive, "correct_total": correct, "gap": naive - correct,
        "naive_parts": (naive_stock, naive_div, naive_call, prem),
        "correct_parts": (corr_stock, corr_div, corr_call, prem),
        "time_value_at_exdiv": crr(S_exdiv, K, 0.05, 0.0, 0.20, 20 / 365,
                                   american=False) - max(S_exdiv - K, 0.0),
        "dividend": dividend,
    }


if __name__ == "__main__":
    print("1. EARLY EXERCISE  American vs European call, S=100 K=90, 30 days\n")
    print(f"   {'div yield':>10} {'European':>10} {'American':>10} "
          f"{'early prem':>12} {'intrinsic':>10}")
    rows = early_exercise_premium()
    for q, e, a, prem, intr in rows:
        tag = "  <- exercise NOW" if abs(a - intr) < 1e-6 else ""
        print(f"   {q:>9.0%} {e:>10.4f} {a:>10.4f} {prem:>12.4f} {intr:>10.2f}{tag}")

    q0 = rows[0]
    print(f"\n   At q=0 the premium is {q0[3]:.4f} — a non-dividend-paying American call")
    print(f"   is never exercised early, which is why the trap only appears on payers.")
    qhi = rows[-1]
    print(f"   At q={qhi[0]:.0%} the American value IS the intrinsic {qhi[4]:.2f}: hold it and you")
    print(f"   lose. European pricing says {qhi[1]:.4f}, understating it by "
          f"{100 * (qhi[4] - qhi[1]) / qhi[4]:.1f}%.")

    print("\n\n2. PIN RISK  short 10 calls struck at 100, at the closing bell\n")
    print(f"   {'settle':>8} {'vs strike':>10} {'OCC':>16} {'shares Monday':>15} "
          f"{'notional':>12}")
    for S, d, auto, sh, notional in pin_exposure():
        print(f"   {S:>8.2f} {d:>+10.2f} {auto:>16} {sh:>15,} {notional:>12,.0f}")
    print("\n   One cent of settlement price decides whether you start Monday flat or")
    print("   short 1,000 shares. The holder can also submit contrary instructions,")
    print("   so even the auto-exercise column is a default, not a guarantee.")

    print("\n\n3. COVERED CALL assigned early at the ex-dividend date\n")
    print("   The position is closed at the ex-div date either way. What the naive")
    print("   accounting does is keep it open and let the rest of the path count.\n")
    print(f"   {'expiry price':>13} {'naive':>10} {'with assignment':>17} {'error':>10}")
    for S_exp in (110.0, 103.0, 96.0):
        rr = covered_call_pnl(S_expiry=S_exp)
        sign = "overstates" if rr["gap"] > 0 else "UNDERstates"
        print(f"   {S_exp:>13.2f} {rr['naive_total']:>10,.0f} "
              f"{rr['correct_total']:>17,.0f} {rr['gap']:>+10,.0f}  {sign}")

    r = covered_call_pnl()
    print(f"\n   The error is not a constant bias — it changes SIGN with the path after")
    print(f"   the assignment date. A backtest carrying an already-assigned position")
    print(f"   forward is not paying a fixed haircut, it is trading a position that")
    print(f"   does not exist, and that shows up as noise you cannot calibrate away.")
    print(f"\n   Why assignment happens here: at the ex-dividend date the call's remaining")
    print(f"   time value is {r['time_value_at_exdiv']:.4f} against a dividend of "
          f"{r['dividend']:.2f}. A rational holder")
    print(f"   exercises to capture the dividend whenever time value < dividend.")

    try:
        import QuantLib as ql

        ql.Settings.instance().evaluationDate = ql.Date(4, 9, 2026)
        today, cal, dc = ql.Date(4, 9, 2026), ql.NullCalendar(), ql.Actual365Fixed()
        spot = ql.SimpleQuote(100.0)

        def qlprice(q, american):
            payoff = ql.PlainVanillaPayoff(ql.Option.Call, 90.0)
            exp = today + 30
            ex = ql.AmericanExercise(today, exp) if american else ql.EuropeanExercise(exp)
            o = ql.VanillaOption(payoff, ex)
            proc = ql.BlackScholesMertonProcess(
                ql.QuoteHandle(spot),
                ql.YieldTermStructureHandle(ql.FlatForward(today, q, dc)),
                ql.YieldTermStructureHandle(ql.FlatForward(today, 0.05, dc)),
                ql.BlackVolTermStructureHandle(ql.BlackConstantVol(today, cal, 0.20, dc)))
            o.setPricingEngine(ql.BinomialVanillaEngine(proc, "crr", 800))
            return o.NPV()

        print(f"\n\n   verified against QuantLib {ql.__version__}:")
        worst = 0.0
        for q, e, a, _, _ in rows:
            qe, qa = qlprice(q, False), qlprice(q, True)
            worst = max(worst, abs(qe - e), abs(qa - a))
            print(f"     q={q:<5.0%} European {qe:>9.4f} vs {e:>9.4f}   "
                  f"American {qa:>9.4f} vs {a:>9.4f}")
        print(f"     worst absolute disagreement: {worst:.2e}")
    except ImportError:
        print("\n\n   QuantLib not installed — binomial tree values only")

    print("\n\n   Rule: an options backtest must model assignment, not just expiry."
          "\n         Mark short American options for early exercise whenever remaining"
          "\n         time value falls below the dividend, and treat any position open"
          "\n         at expiry within a cent of the strike as an unknown exposure.")
